import type { APIRoute } from 'astro';
import { getClientIp } from '@/lib/rateLimit';
import { waitlistRateLimit } from '@/lib/waitlistRateLimit';

export const prerender = false;

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export const POST: APIRoute = async ({ request }) => {
  const ip = getClientIp(request.headers);

  let body: any;
  try {
    body = await request.json();
  } catch {
    return Response.json({ error: 'Body must be JSON.' }, { status: 400 });
  }
  const email = typeof body?.email === 'string' ? body.email.trim() : '';
  if (!email || !EMAIL_RE.test(email) || email.length > 254) {
    return Response.json({ error: 'Invalid email.' }, { status: 400 });
  }

  const rl = waitlistRateLimit(ip);
  if (!rl.ok) {
    const mins = Math.ceil(rl.resetIn / 60000);
    return Response.json(
      { error: `Rate limit hit (5/hr). Try again in ~${mins} min.` },
      { status: 429 },
    );
  }

  const apiKey = [REDACTED];
  if (!apiKey) {
    return Response.json(
      { error: 'Server misconfigured: RESEND_API_KEY missing.' },
      { status: 500 },
    );
  }

  const ts = new Date().toISOString();
  const ua = request.headers.get('user-agent') || '';
  const referer = request.headers.get('referer') || '';
  const text = [
    `email: ${email}`,
    `timestamp: ${ts}`,
    `ip: ${ip}`,
    `user-agent: ${ua}`,
    `referer: ${referer}`,
  ].join('\n');

  try {
    const res = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: {
        'authorization': `Bearer ${apiKey}`,
        'content-type': 'application/json',
      },
      body: JSON.stringify({
        from: 'waitlist@west0n.top',
        to: ['agent+jsontosdk-waitlist@west0n.top'],
        subject: `jsontosdk waitlist: ${email}`,
        text,
      }),
    });
    if (!res.ok) {
      const detail = await res.text().catch(() => '');
      return Response.json(
        { error: `Mail provider error (${res.status}): ${detail.slice(0, 200)}` },
        { status: 502 },
      );
    }
  } catch (e: any) {
    return Response.json(
      { error: 'Mail provider unreachable: ' + (e?.message || 'fetch failed') },
      { status: 502 },
    );
  }

  // Auto-reply to the user — fire-and-forget. Any failure here is swallowed:
  // the inbound notification already succeeded, so the waitlist signup is
  // captured. The user-facing auto-reply is a best-effort "personal touch"
  // that also seeds Q3 reply-thread evidence; it must NEVER fail the request.
  try {
    const replyText = [
      'Hi,',
      '',
      "Thanks for joining the jsontosdk waitlist — you're in line for v2 (API + CLI).",
      '',
      "Quick favor: what API or endpoint are you trying to type? Just hit reply with a URL or the JSON shape, and I'll prioritize that pattern when v2 ships.",
      '',
      '— jsontosdk',
    ].join('\n');
    const replyRes = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: {
        'authorization': `Bearer ${apiKey}`,
        'content-type': 'application/json',
      },
      body: JSON.stringify({
        from: 'jsontosdk@west0n.top',
        to: [email],
        subject: 'Welcome to jsontosdk — quick question',
        text: replyText,
      }),
    });
    if (!replyRes.ok) {
      const detail = await replyRes.text().catch(() => '');
      console.error(
        `waitlist auto-reply non-2xx (${replyRes.status}): ${detail.slice(0, 200)}`,
      );
    }
  } catch (e: any) {
    console.error('waitlist auto-reply threw:', e?.message || e);
  }

  return Response.json(
    { ok: true },
    { headers: { 'x-ratelimit-remaining': String(rl.remaining) } },
  );
};

import type { APIRoute } from 'astro';
import Anthropic from '@anthropic-ai/sdk';
import { rateLimit, getClientIp } from '@/lib/rateLimit';

export const prerender = false;

const MAX_BYTES = 100 * 1024;
const MODEL = 'claude-haiku-4-5';

const SYSTEM_PROMPT = `You convert a single JSON sample into production-grade TypeScript types and a matching Zod schema.

Rules:
- Infer a sensible PascalCase name for the root type from context (singular noun: "User" if the shape looks like one user, "Post" if it looks like a post). Default to "Root" only if no name is plausible.
- Each nested object MUST become a separately-named interface, named after its key in the parent (singular form: "posts": [...] → Post[]). Snake_case keys keep their casing in field names but interfaces are PascalCase.
- Arrays of objects: emit the element interface and use ElementName[].
- Detect: ISO 8601 dates → "string  // ISO 8601 date" (keep type as string), URLs → "string  // URL", emails → "string  // email", enums → string literal unions when the sample suggests them (rare from one sample — only if obvious).
- Numbers: use \`number\` (TS has no separate int/float).
- Null fields: emit \`field: T | null\`. Missing fields are not nullable.
- Arrays of mixed primitives → union element type. Empty arrays → \`unknown[]\` with a comment.
- The Zod schema must mirror the interfaces exactly (z.object, z.array, z.string(), z.number(), z.boolean(), z.nullable(...) for nullables). Export each schema and infer the matching type via z.infer where useful, but the primary types come from the interfaces file.
- Output is JSON only (no markdown fences, no commentary outside the JSON), with shape: {"types": "<typescript code as a single string>", "schema": "<typescript code that imports z from 'zod'>"}.

PROVENANCE HEADER: every output starts with a provenance comment as its first line, so downstream devs opening the file later see where it came from. Both \`schema\` (the Zod file) and \`types\` (the interfaces file) first line is \`// Generated by jsontosdk — edit freely\`.

- "types" file: Line 1: \`// Generated by jsontosdk — edit freely\` then only \`export interface\` declarations, ordered child-first so each interface is defined before it is referenced.
- "schema" file: Line 1: \`// Generated by jsontosdk — edit freely\` then Line 2: \`import { z } from "zod";\`, then \`export const FooSchema = z.object({...});\` declarations, child-first ordering.
- No trailing newlines beyond what's natural. No \`any\`. No leading explanation comments.`;

type Out = { types: string; schema: string };

export const POST: APIRoute = async ({ request }) => {
  return await respond(await parseRequest(request));
};

async function parseRequest(request: Request): Promise<
  | { ok: false; status: number; error: string }
  | { ok: true; json: string; ip: string }
> {
  const ip = getClientIp(request.headers);
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return { ok: false, status: 400, error: 'Body must be JSON.' };
  }
  if (!body || typeof body !== 'object' || typeof (body as any).json !== 'string') {
    return { ok: false, status: 400, error: 'Expected {"json": "<json string>"}.' };
  }
  const json = (body as any).json as string;
  const bytes = new TextEncoder().encode(json).length;
  if (bytes === 0) return { ok: false, status: 400, error: 'JSON input is empty.' };
  if (bytes > MAX_BYTES) {
    return { ok: false, status: 413, error: `JSON exceeds 100 KB (${bytes} bytes).` };
  }
  try {
    JSON.parse(json);
  } catch (e: any) {
    return { ok: false, status: 400, error: 'Invalid JSON: ' + (e?.message || 'parse error') };
  }
  return { ok: true, json, ip };
}

async function respond(
  parsed:
    | { ok: false; status: number; error: string }
    | { ok: true; json: string; ip: string },
): Promise<Response> {
  if (!parsed.ok) {
    return Response.json({ error: parsed.error }, { status: parsed.status });
  }
  const rl = rateLimit(parsed.ip);
  if (!rl.ok) {
    const mins = Math.ceil(rl.resetIn / 60000);
    return Response.json(
      { error: `Rate limit hit (20/hr). Try again in ~${mins} min.` },
      { status: 429 },
    );
  }
  const apiKey = [REDACTED] || process.env.ANTHROPIC_AUTH_TOKEN || process.env.ANTHROPIC;
  if (!apiKey) {
    return Response.json(
      { error: 'Server misconfigured: ANTHROPIC key missing.' },
      { status: 500 },
    );
  }
  try {
    const out = await runClaude(apiKey, parsed.json);
    return Response.json(out, {
      headers: { 'x-ratelimit-remaining': String(rl.remaining) },
    });
  } catch (e: any) {
    const msg = e?.message || 'LLM call failed';
    return Response.json({ error: msg }, { status: 502 });
  }
}

async function runClaude(apiKey: string, json: string): Promise<Out> {
  const client = new Anthropic({ apiKey });
  const msg = await client.messages.create({
    model: MODEL,
    max_tokens: 4096,
    system: SYSTEM_PROMPT,
    messages: [
      {
        role: 'user',
        content: 'JSON sample:\n\n```json\n' + json + '\n```\n\nReturn only the JSON object as specified.',
      },
    ],
  });
  const textBlock = msg.content.find((b) => b.type === 'text');
  if (!textBlock || textBlock.type !== 'text') {
    throw new Error('No text in model response.');
  }
  const raw = textBlock.text.trim();
  const parsed = extractJson(raw);
  if (!parsed || typeof parsed.types !== 'string' || typeof parsed.schema !== 'string') {
    throw new Error('Model returned malformed payload.');
  }
  return { types: parsed.types.trim(), schema: parsed.schema.trim() };
}

function extractJson(text: string): { types?: unknown; schema?: unknown } | null {
  // Tolerate ```json fences even though we tell the model not to use them.
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  const candidate = (fenced ? fenced[1] : text).trim();
  try {
    return JSON.parse(candidate);
  } catch {
    // Last-ditch: find first { and last }
    const start = candidate.indexOf('{');
    const end = candidate.lastIndexOf('}');
    if (start >= 0 && end > start) {
      try {
        return JSON.parse(candidate.slice(start, end + 1));
      } catch {
        return null;
      }
    }
    return null;
  }
}

// In-memory IP rate limiter. Lives per serverless invocation, so it resets on
// cold start — fine for v1 viral-burst cost protection. Move to Vercel KV in v2
// when we need persistence across function instances.

type Bucket = { count: number; windowStart: number };

const WINDOW_MS = 60 * 60 * 1000;
const LIMIT = 20;
const buckets = new Map<string, Bucket>();

export function rateLimit(ip: string): { ok: boolean; remaining: number; resetIn: number } {
  const now = Date.now();
  const b = buckets.get(ip);
  if (!b || now - b.windowStart >= WINDOW_MS) {
    buckets.set(ip, { count: 1, windowStart: now });
    return { ok: true, remaining: LIMIT - 1, resetIn: WINDOW_MS };
  }
  if (b.count >= LIMIT) {
    return { ok: false, remaining: 0, resetIn: WINDOW_MS - (now - b.windowStart) };
  }
  b.count += 1;
  return { ok: true, remaining: LIMIT - b.count, resetIn: WINDOW_MS - (now - b.windowStart) };
}

export function getClientIp(headers: Headers): string {
  const fwd = headers.get('x-forwarded-for');
  if (fwd) return fwd.split(',')[0].trim();
  const real = headers.get('x-real-ip');
  if (real) return real.trim();
  return 'unknown';
}

// Separate in-memory bucket for /api/waitlist so a waitlist signup does not
// consume a /api/generate quota slot. 5 hits / hour / IP.

type Bucket = { count: number; windowStart: number };

const WINDOW_MS = 60 * 60 * 1000;
const LIMIT = 5;
const buckets = new Map<string, Bucket>();

export function waitlistRateLimit(ip: string): { ok: boolean; remaining: number; resetIn: number } {
  const now = Date.now();
  const b = buckets.get(ip);
  if (!b || now - b.windowStart >= WINDOW_MS) {
    buckets.set(ip, { count: 1, windowStart: now });
    return { ok: true, remaining: LIMIT - 1, resetIn: WINDOW_MS };
  }
  if (b.count >= LIMIT) {
    return { ok: false, remaining: 0, resetIn: WINDOW_MS - (now - b.windowStart) };
  }
  b.count += 1;
  return { ok: true, remaining: LIMIT - b.count, resetIn: WINDOW_MS - (now - b.windowStart) };
}
